```
const movies = [
  { title: "Movie 1", rating: 7 },
  { title: "Movie 2", rating: 9 },
  { title: "Movie 3", rating: 6 },
  { title: "Movie 4", rating: 8 },
  { title: "Movie 5", rating: 5 }
];

const sum = movies.reduce((acc, cur) => acc + cur.rating, 0);
const average = sum / movies.length;

