    }
  ]
});
```

В этом примере мы используем `import` для динамической загрузки компонента `DynamicComponent.vue` из нашего `components` каталога. Вы можете использовать аргумент в функции `component` для загрузки динамически.

Без проблем! Вы можете передать props в ваш компонент, используя объект `props` в вашем маршруте. Например:

```javascript
const router = new VueRouter({
