Для создания зависимых списков с помощью select2.js нужно использовать функцию AJAX. В первом списке пользователь выбирает значение, а затем в зависимости от этого значения загружаются соответствующие опции для второго списка. Вот пример кода для такой реализации:

```javascript
$('#first_select').select2({
  placeholder: 'Выберите значение',
  ajax: {
    url: 'url_to_data_source',
    dataType: 'json',
    type: 'GET',
    data: function (params) {
      return {
        q: params.term,
        page: params.page
      };
    },
    processResults: function (data) {
      return {
        results: data.items
      };
    },
    cache: true
  },
});

$('#second_select').select2({
  placeholder: 'Выберите значение',
  ajax: {
    url: function () {
      var first_select_val = $('#first_select').val();
      return 'url_to_data_source/' + first_select_val;
    },
    dataType: 'json',
    type: 'GET',
    data: function (params) {
      return {
        q: params.term,
        page: params.page
      };
    },
    processResults: function (data) {
      return {
        results: data.items
      };
    },
    cache: true
  }
});
```

