Вы можете использовать метод `MutationObserver`, который отслеживает изменения в DOM-дереве и вызывает функцию обратного вызова в момент изменения. Например, вы можете создать новый экземпляр `MutationObserver` и указать в нем, что вы хотите отслеживать изменения в стиле элемента. Код может выглядеть примерно так:

``` javascript
var observer = new MutationObserver(function(mutationsList) {
  for(var mutation of mutationsList) {
    if (mutation.type === 'attributes' && mutation.attributeName === 'style') { 
      // стиль элемента был изменен
      var element = mutation.target;
      var height = element.offsetHeight;
      // делаем что-то с height...
      element.style.height = height + 'px';
    }
  }
});

var config = { attributes: true, attributeFilter: ['style'] };
var target = document.getElementById('example');
observer.observe(target, config);
```

