```
def find_path_to_value(dictionary, value, path=[]):
    for key, item in dictionary.items():
        new_path = path + [key]
        if item == value:
            return new_path
        elif isinstance(item, dict):
            sub_path = find_path_to_value(item, value, new_path)
            if sub_path:
                return sub_path
    return None
```

